"""Build a self-contained comparison from the scored artifact and operator census."""
import json,pathlib,sys
r=json.load(open(sys.argv[1]));survey=json.load(open(sys.argv[2]));out=pathlib.Path(sys.argv[3])
data={'groups':r['physicalGroups'],'games':[g for g in r['candidateGames']if g['completed90Minutes']],'decision':r['normalDecision'],'survey':survey,'policy':r.get('primaryPhysicalPolicy')}
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>d39 pearls measurements</title><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground);line-height:1.45}h2{font-size:19px;margin:22px 0 10px}p{margin:8px 0}small,.muted{color:var(--muted-foreground)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:12px}.box{padding:16px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius,10px)}.big{font-size:24px;font-weight:650;font-variant-numeric:tabular-nums}.row{display:flex;justify-content:space-between;gap:10px;align-items:center}.legend span{margin-right:12px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px}label{font-size:13px}select,input{accent-color:var(--primary)}select{max-width:100%;padding:6px;border:1px solid var(--border);border-radius:6px;background:var(--background);color:var(--foreground)}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px 4px;border-bottom:1px solid var(--border);font-variant-numeric:tabular-nums}td:first-child{font-family:var(--font-mono,monospace);font-size:12px}.bar{height:8px;border-radius:4px;margin-top:4px;min-width:1px}.map{width:100%;height:300px;display:block}button{font:inherit}.facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.facts span{display:block;font-size:12px;color:var(--muted-foreground)}.facts b{font-size:18px;font-variant-numeric:tabular-nums}svg text{fill:var(--muted-foreground);font-size:10px}input[type=range]{width:100%}.note{font-size:12px;color:var(--muted-foreground)}
</style></head><body>
<div class="grid"><div class="box"><div class="muted">Pearls retained at game end</div><div class="big" id="pearl-summary"></div><p class="note">Four seed starts, Sol low/default, 90-minute budgets. Player code frozen at af6f3f09; final container wording was tested separately in decisions.</p></div><div class="box"><div class="muted">Normal decision evaluation</div><div class="big" id="decision"></div><p class="note">Base → candidate, good choices out of 66. Same-family medium judge. Passing the regression gate does not establish improvement; no physical continuation.</p></div></div>
<h2>Gold in a ten-minute opportunity</h2><div class="row"><p class="note">Three repeats per arm/seed; each pair uses the same host.</p><label>Show <select id="metric"><option value="securedMeanPerOpportunity">Secured new gold</option><option value="grossMeanPerOpportunity">Gross new pickups</option></select></label></div><table><thead><tr><th>Seed</th><th>Base 4682f12e</th><th>Candidate</th></tr></thead><tbody id="physical"></tbody></table><p class="note">Ingots or nugget equivalents. Death ends an attempt early and scores zero secured gold; yields are not extrapolated. Both arms use the same model-free policy, which never consumes the changed fact. Differences do not establish a fact-driven physical improvement.</p>
<h2>Completed candidate games</h2><div id="games" class="grid"></div><p class="note">Gold pickups are gross and can include recovered own drops. End gold includes starting currency. Handovers, dropped ingots and heard starts are separate from proven completed barter cycles. Interrupted Desktop games are void and omitted.</p>
<h2>Operator census near each portal</h2><div class="box"><div class="row"><select id="seed" aria-label="Census seed"></select><label><input type="checkbox" id="zoom"> Portal area</label></div><svg id="map" class="map" viewBox="0 0 500 300" role="img" aria-label="Operator gold census, north up"></svg><p id="map-caption" class="note"></p><div class="legend note"><span><i class="dot" style="background:#d5a21e"></i>Surveyed gold blocks</span><span><i class="dot" style="background:#b2694c"></i>Ore on walk graph</span><span><i class="dot" style="background:#5e8aa8"></i>Chests</span></div><p class="note">Operator-only data, never supplied to Sol. Approximate full-block walk graph; no digging, bridging or mob-safety proof. None of the bastion gold was reachable on that unmodified graph.</p></div>
<h2>What the barter odds mean</h2><div class="box"><div class="row"><label for="gold">Ingots offered: <b id="gold-n"></b></label><b id="odds"></b></div><input id="gold" type="range" min="0" max="500" step="1" value="225"><p class="note">Chance of at least twelve pearls. Vanilla: pearl weight 10/469, two to four per pearl trade. Mean stopping cost 204.97 ingots; median 189; 90% budget 340. This assumes all ingots are actually traded.</p></div>
<script>const D=__DATA__;
const fmt=n=>n==null?'unavailable':Number(n).toFixed(3).replace(/\\.?0+$/,'');
const gameOrder=['123456789','8675309','987654321','20261024'];D.games.sort((a,b)=>gameOrder.indexOf(a.seed)-gameOrder.indexOf(b.seed));
document.getElementById('pearl-summary').textContent=`${D.games.filter(g=>g.endPearls>=12).length}/${D.games.length} held at least 12`;
document.getElementById('decision').textContent=`${D.decision.baseGood}/${D.decision.baseN} → ${D.decision.candidateGood}/${D.decision.candidateN}`;
function bars(){const key=document.getElementById('metric').value,max=Math.max(1,...D.groups.map(g=>g[key]||0));document.getElementById('physical').innerHTML=gameOrder.map(seed=>{const cells=['base','candidate'].map((arm,i)=>{const g=D.groups.find(v=>v.seed===seed&&v.arm===arm);return `<td>${fmt(g?.[key])}<div class="bar" style="width:${100*(g?.[key]||0)/max}%;background:var(--chart-${i+1})"></div><small>${g?.deaths??'?'} deaths / ${g?.n??0}</small></td>`;});return `<tr><td>${seed}</td>${cells.join('')}</tr>`;}).join('');}document.getElementById('metric').onchange=bars;bars();
document.getElementById('games').innerHTML=D.games.map(g=>`<div class="box"><div class="row"><b>${g.seed}</b><small>${g.machine}</small></div><div class="facts"><div><span>Gold pickups, gross</span><b>${fmt(g.grossGoldIngots)}</b></div><div><span>Gold held at end</span><b>${fmt(g.endGoldIngots)}</b></div><div><span>Pearls held at end</span><b>${g.endPearls}</b></div><div><span>Deaths</span><b>${g.deaths}</b></div></div><small>Handovers / dropped ingots / heard starts: ${g.handovers} / ${g.droppedIngots} / ${g.heardBarterStarts}</small></div>`).join('');
const selector=document.getElementById('seed');selector.innerHTML=gameOrder.map(s=>`<option>${s}</option>`).join('');
function census(){const s=D.survey.find(v=>String(v.seed)===selector.value),p=s.portal,points=[];for(const b of s.bastions){for(const a of b.goldPositions)points.push({a,color:'#d5a21e',type:'Gold block'});for(const c of b.chests)points.push({a:c.at,color:'#5e8aa8',type:'Chest'});}for(const o of s.oreReachableByUnmodifiedWalking)points.push({a:o.at,color:'#b2694c',type:`Ore; ${o.walkSteps} route steps`});const near=document.getElementById('zoom').checked;const limit=near?112:Math.max(112,...points.flatMap(v=>[Math.abs(v.a[0]-p[0]),Math.abs(v.a[2]-p[2])]))*1.1;const scale=130/limit,x=n=>250+n*scale,y=n=>150+n*scale;document.getElementById('map').innerHTML=`<path d="M120 150H380M250 20V280" stroke="var(--border)"/><text x="255" y="15">N</text><text x="385" y="153">E</text><text x="122" y="292">±${Math.round(limit)} m from portal</text>`+points.filter(v=>Math.abs(v.a[0]-p[0])<=limit&&Math.abs(v.a[2]-p[2])<=limit).map(v=>`<circle cx="${x(v.a[0]-p[0])}" cy="${y(v.a[2]-p[2])}" r="${v.type==='Gold block'?3:2}" fill="${v.color}"><title>${v.type}: ${v.a.join(',')}; y offset ${v.a[1]-p[1]}</title></circle>`).join('')+`<rect x="246" y="146" width="8" height="8" fill="var(--foreground)"><title>Portal ${p.join(',')}</title></rect>`;document.getElementById('map-caption').textContent=`${s.bastions.reduce((n,b)=>n+b.actualGoldBlocks,0)} surveyed gold blocks across ${s.bastions.length} bastion(s); ${s.oreReachableByUnmodifiedWalking.length} ore cells visible from the approximate portal walk graph. Gold positions can be far below portal height.`;}selector.onchange=census;document.getElementById('zoom').onchange=census;census();
function probability(n){let a=Array(12).fill(0);a[0]=1;for(let i=0;i<n;i++){const b=a.map(x=>x*459/469);for(let j=0;j<12;j++)for(let k=2;k<=4;k++)if(j+k<12)b[j+k]+=a[j]*10/469/3;a=b;}return 1-a.reduce((x,y)=>x+y,0);}function price(){const n=Number(document.getElementById('gold').value);document.getElementById('gold-n').textContent=n;document.getElementById('odds').textContent=(100*probability(n)).toFixed(2)+'% chance';}document.getElementById('gold').oninput=price;price();
</script></body></html>'''
out.write_text(page.replace('__DATA__',json.dumps(data,separators=(',',':'))));print(out)
